// revolve: a knob: a profile (radius 15 at the base, 12 at the top, 20 tall) revolved, its top edge filleted 3 mm and base chamfered 1 mm, a hole (radius 1.5, 8 deep) at 6 from the axis patterned 4 round it
export function c007(context is Context, id is Id)
{
    const profile = newSketchOnPlane(context, id + "profile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(profile, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(15, 0) * millimeter });
    skLineSegment(profile, "l2", { "start" : vector(15, 0) * millimeter, "end" : vector(12, 20) * millimeter });
    skLineSegment(profile, "l3", { "start" : vector(12, 20) * millimeter, "end" : vector(0, 20) * millimeter });
    skLineSegment(profile, "l4", { "start" : vector(0, 20) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(profile);
    const axis = newSketchOnPlane(context, id + "axis", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis, "line1", { "start" : vector(-50, 0) * millimeter, "end" : vector(50, 0) * millimeter });
    skSolve(axis);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "profile"), "axis" : qCreatedBy(id + "axis", EntityType.EDGE), "fullRevolve" : true });
    fillet(context, id + "fillet1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(12, 0, 20) * millimeter), "radius" : 3 * millimeter });
    chamfer(context, id + "chamfer1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(15, 0, 0) * millimeter), "chamferType" : ChamferType.EQUAL_OFFSETS, "width" : 1 * millimeter });
    const holeSketch = newSketchOnPlane(context, id + "holeSketch", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(holeSketch, "c1", { "center" : vector(6, 0) * millimeter, "radius" : 1.5 * millimeter });
    skSolve(holeSketch);
    extrude(context, id + "hole", { "entities" : qSketchRegion(id + "holeSketch"), "endBound" : BoundingType.BLIND, "depth" : 8 * millimeter, "oppositeDirection" : true, "operationType" : NewBodyOperationType.REMOVE, "defaultScope" : false, "booleanScope" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID) });
    circularPattern(context, id + "pattern1", { "patternType" : PatternType.FEATURE, "instanceFunction" : { (id + "hole") : function(instanceId) { extrude(context, instanceId, { "entities" : qSketchRegion(id + "holeSketch"), "endBound" : BoundingType.BLIND, "depth" : 8 * millimeter, "oppositeDirection" : true, "operationType" : NewBodyOperationType.REMOVE, "defaultScope" : false, "booleanScope" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID) }); } } as FeatureList, "axis" : qCreatedBy(id + "axis", EntityType.EDGE), "angle" : 360 * degree, "instanceCount" : 4, "equalSpace" : true, "fullFeaturePattern" : false });
}

